/* DHYEYA — account foundation + production hooks */
(()=>{
 const API='/api'; let student=null;
 const $=s=>document.querySelector(s);
 const esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
 async function api(path,opts={}){const r=await fetch(API+path,{credentials:'include',headers:{'Content-Type':'application/json',...(opts.headers||{})},...opts});let d={};try{d=await r.json()}catch{}if(!r.ok)throw new Error(d.error||'Request failed');return d}
 function mountAuth(){if($('#nexusAuthMount'))return;const m=document.createElement('div');m.id='nexusAuthMount';m.innerHTML=`<div id="nexusAuthModal" class="modal" aria-hidden="true"><div class="modalbox" style="max-width:480px"><div class="modalhead"><div><div class="eyebrow">DHYEYA</div><h2 id="nexusAuthTitle" style="margin:6px 0">Sign in</h2><p id="nexusAuthSub" class="sub">Use your Student ID, username or email.</p></div><button class="close" id="nexusAuthClose">×</button></div><div style="display:grid;gap:12px;margin-top:18px"><input id="nxName" class="field-input" placeholder="Full name" style="display:none;background:#0d1115;border:1px solid var(--line);color:var(--text);border-radius:11px;padding:12px"><input id="nxEmail" class="field-input" placeholder="Student ID / username / email" style="background:#0d1115;border:1px solid var(--line);color:var(--text);border-radius:11px;padding:12px"><input id="nxPassword" class="field-input" type="password" placeholder="Password" style="background:#0d1115;border:1px solid var(--line);color:var(--text);border-radius:11px;padding:12px"><input id="nxUsername" class="field-input" placeholder="Username (optional)" style="display:none;background:#0d1115;border:1px solid var(--line);color:var(--text);border-radius:11px;padding:12px"><button id="nxSubmit" class="btn primary">Sign in</button><button id="nxSwitch" class="btn ghost">Create account</button><div id="nxAuthError" class="sub" style="color:#ff9ca1;min-height:18px"></div></div></div></div>`;document.body.appendChild(m);$('#nexusAuthClose').onclick=closeAuth;$('#nxSwitch').onclick=()=>setMode(!window.__nxSignup);$('#nxSubmit').onclick=submitAuth}
 function setMode(signup){window.__nxSignup=signup;$('#nexusAuthTitle').textContent=signup?'Create your account':'Sign in';$('#nexusAuthSub').textContent=signup?'Create a student account for your preparation.':'Use your Student ID, username or email.';$('#nxName').style.display=signup?'block':'none';$('#nxUsername').style.display=signup?'block':'none';$('#nxSubmit').textContent=signup?'Create account':'Sign in';$('#nxSwitch').textContent=signup?'Already have an account? Sign in':'Create account';$('#nxAuthError').textContent='';}
 function openAuth(signup=false){mountAuth();setMode(signup);$('#nexusAuthModal').classList.add('show');$('#nexusAuthModal').setAttribute('aria-hidden','false')}
 function closeAuth(){const x=$('#nexusAuthModal');if(x){x.classList.remove('show');x.setAttribute('aria-hidden','true')}}
 async function submitAuth(){try{const identifier=$('#nxEmail').value.trim(),password=$('#nxPassword').value;let body;if(window.__nxSignup){body={email:identifier,password,name:$('#nxName').value.trim(),username:$('#nxUsername').value.trim()||undefined};if(!body.name)throw Error('Name is required')}else body={identifier,password};const d=await api(window.__nxSignup?'/auth/register':'/auth/login',{method:'POST',body:JSON.stringify(body)});student=d.user;closeAuth();hydrate();updateAccountButton();toast('Welcome, '+student.name);if(student.role==='admin')mountAdminTools()}catch(e){$('#nxAuthError').textContent=e.message}}
 function hydrate(){if(!student)return;document.querySelectorAll('.avatar').forEach(x=>{if(student.avatar_url){x.innerHTML='<img src="'+esc(student.avatar_url)+'" alt="Profile" style="width:100%;height:100%;object-fit:cover;border-radius:inherit">'}else if(x.textContent.trim()==='P'||x.textContent.trim()==='Student')x.textContent=(student.name||'S')[0].toUpperCase()});const prof=document.querySelector('#profile');if(prof){const h=prof.querySelector('h2');if(h)h.textContent=student.name;const sub=prof.querySelector('.sub');if(sub&&/Student ID/.test(sub.textContent))sub.textContent='Student ID: '+(student.student_code||student.id.slice(0,8).toUpperCase())}window.bpnStudent=student;updateAccountButton();mountAdminTools()}
 function mountAccountButton(){
  const top=document.querySelector('.top-actions');
  if(!top||$('#nexusAccountBtn'))return;
  const b=document.createElement('button');b.id='nexusAccountBtn';b.className='iconbtn';b.title='My profile';
  b.style.cssText='width:42px;height:42px;border-radius:14px;padding:0;overflow:hidden;display:grid;place-items:center;font-weight:900';
  b.innerHTML='<span style="font-size:17px">P</span>';
  b.onclick=()=>student?openProfileEditor():openAuth(false);top.prepend(b);updateAccountButton();
 }
 function updateAccountButton(){
  const b=$('#nexusAccountBtn');if(!b)return;
  if(student?.avatar_url)b.innerHTML='<img src="'+esc(student.avatar_url)+'" alt="Profile" style="width:100%;height:100%;object-fit:cover">';
  else b.innerHTML='<span style="font-size:16px">'+esc((student?.name||'P')[0].toUpperCase())+'</span>';
 }
 function profileStyles(){
  if($('#dhyProfileCss'))return;
  const st=document.createElement('style');st.id='dhyProfileCss';st.textContent=`
  .dhy-profile-overlay{position:fixed;inset:0;z-index:10020;background:rgba(7,10,16,.72);backdrop-filter:blur(18px) saturate(120%);display:flex;align-items:center;justify-content:center;padding:18px;animation:dhyFade .18s ease}
  .dhy-profile-card{width:min(760px,96vw);max-height:min(92vh,900px);overflow:auto;background:linear-gradient(180deg,#151a22 0%,#0e1218 100%);color:#f4f7fb;border:1px solid rgba(255,255,255,.11);border-radius:28px;box-shadow:0 35px 120px rgba(0,0,0,.55);position:relative}
  .dhy-profile-hero{padding:24px 26px 20px;background:radial-gradient(circle at 85% 10%,rgba(255,168,58,.24),transparent 35%),linear-gradient(135deg,rgba(255,255,255,.05),rgba(255,255,255,.015));border-bottom:1px solid rgba(255,255,255,.08)}
  .dhy-profile-top{display:flex;justify-content:space-between;gap:14px}.dhy-profile-kicker{font-size:10px;letter-spacing:.19em;font-weight:900;color:#f5b45a}.dhy-profile-title{font-size:27px;font-weight:900;margin:5px 0 4px;letter-spacing:-.03em}.dhy-profile-sub{font-size:12px;color:#8e99a8}
  .dhy-profile-close{width:38px;height:38px;border:1px solid rgba(255,255,255,.09);border-radius:12px;background:rgba(255,255,255,.06);color:#fff;font-size:22px;cursor:pointer}
  .dhy-profile-identity{display:flex;align-items:center;gap:17px;margin-top:22px}.dhy-profile-avatar-wrap{position:relative;flex:0 0 auto}.dhy-profile-avatar{width:94px;height:94px;border-radius:30px;object-fit:cover;display:grid;place-items:center;font-size:32px;font-weight:900;background:linear-gradient(145deg,#f4b25a,#8d4c1d);border:3px solid rgba(255,255,255,.16);box-shadow:0 12px 35px rgba(0,0,0,.3)}
  .dhy-profile-camera{position:absolute;right:-5px;bottom:-5px;width:32px;height:32px;border-radius:11px;background:#fff;color:#15191f;border:3px solid #151a22;display:grid;place-items:center;font-size:14px;cursor:pointer}.dhy-profile-name{font-size:21px;font-weight:850}.dhy-profile-id{display:inline-flex;align-items:center;gap:7px;margin-top:6px;padding:6px 9px;border-radius:999px;background:rgba(255,255,255,.06);border:1px solid rgba(255,255,255,.08);font-size:11px;color:#b8c0cb}.dhy-profile-id b{color:#fff}
  .dhy-profile-body{padding:20px 26px 24px}.dhy-profile-section{margin-top:18px}.dhy-profile-section:first-child{margin-top:0}.dhy-profile-section-title{display:flex;align-items:center;gap:9px;font-size:12px;font-weight:900;text-transform:uppercase;letter-spacing:.11em;color:#aeb8c6;margin-bottom:11px}.dhy-profile-grid{display:grid;grid-template-columns:1fr 1fr;gap:12px}.dhy-profile-field{min-width:0}.dhy-profile-field.full{grid-column:1/-1}.dhy-profile-label{display:block;font-size:10px;font-weight:800;color:#7f8998;margin:0 0 6px 3px}.dhy-profile-input,.dhy-profile-select,.dhy-profile-textarea{width:100%;box-sizing:border-box;border:1px solid rgba(255,255,255,.10);background:rgba(255,255,255,.045);color:#f1f4f8;border-radius:14px;padding:12px 13px;outline:none;font:inherit;font-size:13px;transition:.18s}.dhy-profile-textarea{min-height:86px;resize:vertical}.dhy-profile-input:focus,.dhy-profile-select:focus,.dhy-profile-textarea:focus{border-color:rgba(255,178,82,.75);box-shadow:0 0 0 3px rgba(255,178,82,.10);background:rgba(255,255,255,.065)}.dhy-profile-input[readonly]{color:#aeb7c3;background:rgba(255,255,255,.025)}
  .dhy-profile-note{font-size:10px;color:#707b89;margin-top:6px}.dhy-profile-photo-actions{display:flex;gap:8px;margin-top:8px;flex-wrap:wrap}.dhy-profile-btn{border:1px solid rgba(255,255,255,.11);background:rgba(255,255,255,.055);color:#f2f5f8;border-radius:12px;padding:9px 12px;font-weight:800;font-size:11px;cursor:pointer}.dhy-profile-btn:hover{background:rgba(255,255,255,.09)}.dhy-profile-btn.danger{color:#ff9ca1}.dhy-profile-btn.primary{background:linear-gradient(135deg,#ffad43,#f28b1f);color:#17120c;border:0;box-shadow:0 8px 25px rgba(245,145,40,.2)}
  .dhy-profile-footer{display:flex;align-items:center;justify-content:space-between;gap:10px;margin-top:22px;padding-top:16px;border-top:1px solid rgba(255,255,255,.08);position:sticky;bottom:0;background:linear-gradient(180deg,rgba(14,18,24,.4),#0e1218 35%)}.dhy-profile-status{font-size:11px;color:#ff9ca1;min-height:18px}.dhy-profile-save{min-width:160px;padding:12px 18px;border:0;border-radius:14px;background:linear-gradient(135deg,#ffb44f,#f28b1f);color:#17120c;font-weight:950;cursor:pointer;box-shadow:0 10px 28px rgba(242,139,31,.22)}.dhy-profile-save:disabled{opacity:.65;cursor:wait}.dhy-profile-logout{margin-top:12px;width:100%;padding:10px;border:1px solid rgba(255,112,112,.22);background:rgba(255,70,70,.05);color:#ff9ca1;border-radius:12px;font-weight:800;cursor:pointer}
  @keyframes dhyFade{from{opacity:0;transform:translateY(5px)}to{opacity:1;transform:none}}@media(max-width:640px){.dhy-profile-overlay{padding:0;align-items:flex-end}.dhy-profile-card{width:100%;max-height:96vh;border-radius:26px 26px 0 0}.dhy-profile-hero{padding:20px 18px}.dhy-profile-body{padding:17px 18px 20px}.dhy-profile-title{font-size:24px}.dhy-profile-grid{grid-template-columns:1fr}.dhy-profile-field.full{grid-column:auto}.dhy-profile-footer{align-items:stretch;flex-direction:column}.dhy-profile-save{width:100%}.dhy-profile-identity{gap:13px}.dhy-profile-avatar{width:78px;height:78px;border-radius:24px}}
  `;document.head.appendChild(st);
 }
 function openProfileEditor(){
  if(!student)return openAuth(false);profileStyles();if($('#nexusProfileModal'))$('#nexusProfileModal').remove();
  const m=document.createElement('div');m.id='nexusProfileModal';m.className='dhy-profile-overlay';
  const prefs=student.preferences||{};
  const avatar=student.avatar_url?`<img id="pxAvatarPreview" class="dhy-profile-avatar" src="${esc(student.avatar_url)}" alt="Profile picture">`:`<div id="pxAvatarPreview" class="dhy-profile-avatar">${esc((student.name||'S')[0].toUpperCase())}</div>`;
  m.innerHTML=`<div class="dhy-profile-card" role="dialog" aria-modal="true" aria-label="Edit profile">
   <div class="dhy-profile-hero"><div class="dhy-profile-top"><div><div class="dhy-profile-kicker">DHYEYA • STUDENT ACCOUNT</div><div class="dhy-profile-title">Your Profile</div><div class="dhy-profile-sub">Personalize your identity and study preferences.</div></div><button class="dhy-profile-close" id="nxPClose">×</button></div>
    <div class="dhy-profile-identity"><div class="dhy-profile-avatar-wrap">${avatar}<label class="dhy-profile-camera" for="pxAvatar" title="Change profile picture">✦</label><input id="pxAvatar" type="file" accept="image/jpeg,image/png,image/webp" style="display:none"></div><div><div class="dhy-profile-name" id="pxHeroName">${esc(student.name||'Student')}</div><div class="dhy-profile-id">Student ID <b>${esc(student.student_code||'—')}</b> <span>• fixed</span></div><div class="dhy-profile-photo-actions"><label class="dhy-profile-btn" for="pxAvatar">Change picture</label><button class="dhy-profile-btn danger" id="pxRemoveAvatar" type="button">Remove</button></div></div></div>
   </div>
   <div class="dhy-profile-body">
    <div class="dhy-profile-section"><div class="dhy-profile-section-title">◉ Identity</div><div class="dhy-profile-grid">
      <div class="dhy-profile-field"><label class="dhy-profile-label">Display name</label><input id="pxName" class="dhy-profile-input" maxlength="80" value="${esc(student.name||'')}" placeholder="Your name"></div>
      <div class="dhy-profile-field"><label class="dhy-profile-label">Username</label><input id="pxUsername" class="dhy-profile-input" maxlength="30" value="${esc(student.username||'')}" placeholder="Choose a username"><div class="dhy-profile-note">Used for your public identity.</div></div>
      <div class="dhy-profile-field full"><label class="dhy-profile-label">Bio</label><textarea id="pxBio" class="dhy-profile-textarea" maxlength="180" placeholder="A short line about your preparation…">${esc(student.bio||'')}</textarea></div>
    </div></div>
    <div class="dhy-profile-section"><div class="dhy-profile-section-title">⌁ Preparation</div><div class="dhy-profile-grid">
      <div class="dhy-profile-field"><label class="dhy-profile-label">Target exam</label><input id="pxTarget" class="dhy-profile-input" maxlength="80" value="${esc(student.target_exam||'BPSC Prelims')}" placeholder="Target exam"></div>
      <div class="dhy-profile-field"><label class="dhy-profile-label">Exam date</label><input id="pxExamDate" class="dhy-profile-input" type="date" value="${esc(student.exam_date||'')}"></div>
      <div class="dhy-profile-field"><label class="dhy-profile-label">Daily question target</label><input id="pxDaily" class="dhy-profile-input" type="number" min="1" max="1000" value="${student.daily_target||100}"><div class="dhy-profile-note">Used for missions and daily progress.</div></div>
    </div></div>
    <div class="dhy-profile-section"><div class="dhy-profile-section-title">⚙ Preferences</div><div class="dhy-profile-grid">
      <div class="dhy-profile-field"><label class="dhy-profile-label">Appearance</label><select id="pxTheme" class="dhy-profile-select"><option value="system">System</option><option value="light">Light</option><option value="dark">Dark</option></select></div>
      <div class="dhy-profile-field"><label class="dhy-profile-label">Content language</label><select id="pxLang" class="dhy-profile-select"><option value="en">English</option><option value="hi">Hindi</option><option value="bilingual">Bilingual</option></select></div>
    </div></div>
    <div class="dhy-profile-footer"><div id="pxErr" class="dhy-profile-status"></div><button id="pxSave" class="dhy-profile-save">Save changes</button></div>
    <button id="pxLogout" class="dhy-profile-logout">Log out of DHYEYA</button>
   </div></div>`;
  document.body.appendChild(m);
  $('#pxTheme').value=prefs.theme||'system';$('#pxLang').value=prefs.language||'bilingual';let avatarData=student.avatar_url||null;
  $('#nxPClose').onclick=()=>m.remove();m.addEventListener('click',e=>{if(e.target===m)m.remove()});
  $('#pxAvatar').onchange=async e=>{const f=e.target.files?.[0];if(!f)return;if(f.size>8*1024*1024){$('#pxErr').textContent='Choose an image under 8 MB.';return}try{avatarData=await resizeImage(f);$('#pxAvatarPreview').outerHTML=`<img id="pxAvatarPreview" class="dhy-profile-avatar" src="${esc(avatarData)}" alt="Profile picture">`;$('#pxErr').textContent='Picture ready — save to apply.'}catch{$('#pxErr').textContent='Could not process this image.'}};
  $('#pxRemoveAvatar').onclick=()=>{avatarData=null;$('#pxAvatarPreview').outerHTML=`<div id="pxAvatarPreview" class="dhy-profile-avatar">${esc((student.name||'S')[0].toUpperCase())}</div>`;$('#pxErr').textContent='Picture removed — save to apply.'};
  $('#pxName').oninput=e=>{$('#pxHeroName').textContent=e.target.value.trim()||'Student'};
  $('#pxSave').onclick=async()=>{const save=$('#pxSave');try{save.disabled=true;save.textContent='Saving…';$('#pxErr').textContent='';const name=$('#pxName').value.trim();if(!name)throw Error('Display name is required');const daily=Math.max(1,Math.min(1000,Number($('#pxDaily').value||100)));const preferences={...(student.preferences||{}),theme:$('#pxTheme').value,language:$('#pxLang').value};const d=await api('/profile',{method:'PATCH',body:JSON.stringify({name,username:$('#pxUsername').value.trim()||null,bio:$('#pxBio').value.trim(),avatar_url:avatarData,target_exam:$('#pxTarget').value.trim()||'BPSC Prelims',exam_date:$('#pxExamDate').value||null,daily_target:daily,preferences})});student=d.user;m.remove();hydrate();updateAccountButton();toast('Profile saved successfully')}catch(e){$('#pxErr').textContent=e.message;save.disabled=false;save.textContent='Save changes'}};
  $('#pxLogout').onclick=async()=>{try{await api('/auth/logout',{method:'POST'})}finally{student=null;m.remove();location.reload()}};
 }
 function resizeImage(file){return new Promise((resolve,reject)=>{const r=new FileReader();r.onload=()=>{const img=new Image();img.onload=()=>{const max=512,scale=Math.min(1,max/Math.max(img.width,img.height)),c=document.createElement('canvas');c.width=Math.max(1,Math.round(img.width*scale));c.height=Math.max(1,Math.round(img.height*scale));const ctx=c.getContext('2d');ctx.drawImage(img,0,0,c.width,c.height);resolve(c.toDataURL('image/jpeg',.82))};img.onerror=reject;img.src=r.result};r.onerror=reject;r.readAsDataURL(file)})}
 async function boot(){mountAccountButton();mountAuth();try{student=(await api('/auth/me')).user;hydrate()}catch{student=null}}
 window.NexusFoundation={openAuth,openProfileEditor,api,getStudent:()=>student,refresh:async()=>{try{student=(await api('/auth/me')).user;hydrate()}catch{student=null}return student}};
 window.addEventListener('DOMContentLoaded',boot);
})();

/* DHYEYA V4 — visible Admin Login + Admin Console */
(()=>{
 const api=window.NexusFoundation?.api;
 if(!api) return;
 const esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
 const css=`
 .dhy-admin-btn{border-color:rgba(201,164,92,.38)!important;background:rgba(201,164,92,.08)!important}
 .dhy-admin-modal{position:fixed;inset:0;background:rgba(3,7,12,.78);backdrop-filter:blur(10px);z-index:10050;display:flex;align-items:center;justify-content:center;padding:18px}
 .dhy-admin-box{width:min(980px,96vw);max-height:92vh;overflow:auto;background:#10151b;color:#eef2f6;border:1px solid rgba(255,255,255,.10);border-radius:22px;box-shadow:0 30px 100px rgba(0,0,0,.55)}
 .dhy-admin-login{width:min(430px,94vw);padding:28px}.dhy-admin-head{display:flex;align-items:flex-start;justify-content:space-between;gap:15px;padding:22px;border-bottom:1px solid rgba(255,255,255,.08);position:sticky;top:0;background:rgba(16,21,27,.96);z-index:2}.dhy-admin-body{padding:22px}
 .dhy-admin-kicker{font-size:10px;letter-spacing:.15em;color:#c9a45c;font-weight:800}.dhy-admin-head h2{margin:5px 0;font-size:22px}.dhy-admin-sub{font-size:12px;color:#8f99a6}.dhy-admin-close{border:0;background:rgba(255,255,255,.07);color:#fff;border-radius:10px;padding:8px 11px;cursor:pointer}
 .dhy-admin-input{width:100%;box-sizing:border-box;background:#0b0f13;color:#eef2f6;border:1px solid rgba(255,255,255,.12);border-radius:11px;padding:12px;margin-top:7px;outline:none}.dhy-admin-label{display:block;font-size:11px;color:#aeb7c2;font-weight:700;margin-top:13px}.dhy-admin-primary{width:100%;margin-top:16px;border:0;border-radius:11px;padding:12px;background:#c9a45c;color:#111;font-weight:900;cursor:pointer}.dhy-admin-error{min-height:18px;color:#ff9ca1;font-size:12px;margin-top:10px}
 .dhy-admin-kpis{display:grid;grid-template-columns:repeat(4,1fr);gap:10px}.dhy-kpi{background:#0b0f13;border:1px solid rgba(255,255,255,.07);border-radius:14px;padding:14px}.dhy-kpi small{color:#7f8995;font-size:10px}.dhy-kpi strong{display:block;font-size:24px;margin-top:5px}.dhy-admin-toolbar{display:flex;gap:8px;flex-wrap:wrap;margin:16px 0}.dhy-admin-btn2{border:1px solid rgba(255,255,255,.12);background:#151b22;color:#e9edf1;border-radius:10px;padding:9px 11px;font-weight:750;cursor:pointer}.dhy-admin-btn2.primary{background:#c9a45c;color:#111;border-color:#c9a45c}.dhy-admin-table{width:100%;border-collapse:collapse;font-size:12px}.dhy-admin-table th,.dhy-admin-table td{padding:10px 8px;border-bottom:1px solid rgba(255,255,255,.07);text-align:left}.dhy-admin-table th{font-size:10px;color:#7f8995;text-transform:uppercase}.dhy-status{display:inline-block;padding:4px 8px;border-radius:999px;font-size:10px;font-weight:800}.dhy-status.active{background:#173a29;color:#8ee0b1}.dhy-status.blocked{background:#3d1d20;color:#ff9ca1}.dhy-status.deactivated{background:#3b321d;color:#e8c778}.dhy-muted{color:#7f8995}.dhy-admin-section{background:#0b0f13;border:1px solid rgba(255,255,255,.07);border-radius:15px;padding:15px;margin-top:14px}.dhy-admin-section h3{margin:0 0 10px;font-size:14px}
 @media(max-width:700px){.dhy-admin-kpis{grid-template-columns:repeat(2,1fr)}.dhy-admin-head,.dhy-admin-body{padding:16px}.dhy-admin-table{min-width:720px}.dhy-admin-section{overflow:auto}}
 `;
 function addCss(){if(document.getElementById('dhyAdminCss'))return;const s=document.createElement('style');s.id='dhyAdminCss';s.textContent=css;document.head.appendChild(s)}
 function addQuickTool(){
   const grid=document.querySelector('#utilityPanel .utility-grid');
   if(!grid||document.getElementById('dhyAdminQuickTool'))return;
   const b=document.createElement('button');b.id='dhyAdminQuickTool';b.className='utility-item dhy-admin-btn';b.innerHTML='<span class="uicon">🔐</span><span><b>Admin Login</b><small>Restricted console</small></span>';
   b.onclick=()=>{closeUtilityHub?.();openAdminLogin()};grid.appendChild(b);
 }
 function modal(inner){const d=document.createElement('div');d.className='dhy-admin-modal';d.innerHTML=inner;document.body.appendChild(d);return d}
 function openAdminLogin(){addCss();if(document.querySelector('.dhy-admin-modal'))document.querySelector('.dhy-admin-modal').remove();const m=modal(`<div class="dhy-admin-box dhy-admin-login"><div class="dhy-admin-kicker">DHYEYA • RESTRICTED ACCESS</div><h2 style="margin:6px 0 5px">Admin Login</h2><div class="dhy-admin-sub">Student accounts cannot access this console.</div><label class="dhy-admin-label">Admin Username / Email</label><input id="dhyAU" class="dhy-admin-input" autocomplete="username" placeholder="Admin username or email"><label class="dhy-admin-label">Admin Password</label><input id="dhyAP" class="dhy-admin-input" type="password" autocomplete="current-password" placeholder="Password"><button id="dhyAL" class="dhy-admin-primary">Login to Admin Console</button><div id="dhyAE" class="dhy-admin-error"></div><button id="dhyAC" class="dhy-admin-btn2" style="width:100%;margin-top:8px">Cancel</button></div>`);m.querySelector('#dhyAC').onclick=()=>m.remove();m.querySelector('#dhyAL').onclick=async()=>{const e=m.querySelector('#dhyAE');e.textContent='';try{const d=await api('/auth/login',{method:'POST',body:JSON.stringify({identifier:m.querySelector('#dhyAU').value.trim(),password:m.querySelector('#dhyAP').value})});if(d.user?.role!=='admin'){await api('/auth/logout',{method:'POST'});throw Error('This account is not an administrator.')}m.remove();openAdminConsole(d.user)}catch(x){e.textContent=x.message}};m.querySelector('#dhyAP').addEventListener('keydown',e=>{if(e.key==='Enter')m.querySelector('#dhyAL').click()})}
 async function openAdminConsole(user){addCss();const m=modal(`<div class="dhy-admin-box"><div class="dhy-admin-head"><div><div class="dhy-admin-kicker">DHYEYA ADMIN CONSOLE</div><h2>Control Center</h2><div class="dhy-admin-sub">Signed in as ${esc(user.name||user.username||user.email)}</div></div><button class="dhy-admin-close" id="dhyX">×</button></div><div class="dhy-admin-body"><div id="dhyStats" class="dhy-admin-kpis"><div class="dhy-kpi"><small>Students</small><strong>—</strong></div><div class="dhy-kpi"><small>Active</small><strong>—</strong></div><div class="dhy-kpi"><small>Attempts</small><strong>—</strong></div><div class="dhy-kpi"><small>Questions</small><strong>—</strong></div></div><div class="dhy-admin-toolbar"><button class="dhy-admin-btn2 primary" id="dhyNew">+ Generate Student</button><button class="dhy-admin-btn2" id="dhyRefresh">Refresh</button><button class="dhy-admin-btn2" id="dhyLogout">Admin Logout</button></div><div class="dhy-admin-section"><h3>Student Management</h3><input id="dhySearch" class="dhy-admin-input" placeholder="Search name, email, username or Student ID"><div style="overflow:auto;margin-top:10px"><table class="dhy-admin-table"><thead><tr><th>Student</th><th>ID</th><th>Status</th><th>XP</th><th>Last login</th><th>Actions</th></tr></thead><tbody id="dhyUsers"><tr><td colspan="6" class="dhy-muted">Loading…</td></tr></tbody></table></div></div><div class="dhy-admin-section"><h3>System</h3><div class="dhy-admin-sub">Admin APIs are protected server-side. Student passwords are hashed; account status is enforced by the API; admin actions are written to the audit log.</div></div></div></div>`);m.querySelector('#dhyX').onclick=()=>m.remove();m.querySelector('#dhyRefresh').onclick=()=>load();m.querySelector('#dhySearch').oninput=()=>load();m.querySelector('#dhyLogout').onclick=async()=>{await api('/auth/logout',{method:'POST'});m.remove();toast('Admin logged out')};m.querySelector('#dhyNew').onclick=()=>newStudent();async function load(){try{const s=await api('/admin/stats');const v=s.stats||{};const vals=[v.users,v.active_users,v.attempts,v.questions];m.querySelectorAll('#dhyStats strong').forEach((x,i)=>x.textContent=vals[i]??0);const q=encodeURIComponent(m.querySelector('#dhySearch').value.trim());const d=await api('/admin/users'+(q?'?search='+q:''));m.querySelector('#dhyUsers').innerHTML=(d.users||[]).map(u=>`<tr><td><b>${esc(u.name)}</b><br><span class="dhy-muted">${esc(u.email||u.username||'')}</span></td><td>${esc(u.student_code||'—')}</td><td><span class="dhy-status ${esc(u.status)}">${esc(u.status)}</span></td><td>${u.xp||0}</td><td>${u.last_login_at?new Date(u.last_login_at).toLocaleString():'Never'}</td><td><button class="dhy-admin-btn2" data-action="status" data-id="${u.id}" data-status="${u.status==='active'?'blocked':'active'}">${u.status==='active'?'Block':'Activate'}</button> <button class="dhy-admin-btn2" data-action="reset" data-id="${u.id}">Reset Password</button></td></tr>`).join('')||'<tr><td colspan="6" class="dhy-muted">No students found.</td></tr>';m.querySelectorAll('[data-action]').forEach(b=>b.onclick=async()=>{try{if(b.dataset.action==='status'){await api('/admin/users/'+b.dataset.id+'/status',{method:'PATCH',body:JSON.stringify({status:b.dataset.status})});toast('Account status updated');await load()}else{const r=await api('/admin/users/'+b.dataset.id+'/reset-password',{method:'POST',body:JSON.stringify({})});alert('Temporary password for '+r.user.student_code+':\n\n'+r.temporary_password);}}catch(e){alert(e.message)}})}catch(e){m.querySelector('#dhyUsers').innerHTML='<tr><td colspan="6" style="color:#ff9ca1">'+esc(e.message)+'</td></tr>'}}async function newStudent(){const name=prompt('Student name');if(!name)return;const email=prompt('Email (optional)')||'';const password=prompt('Temporary password (leave blank to generate)')||'';try{const d=await api('/admin/users',{method:'POST',body:JSON.stringify({name,email:email||null,password:password||undefined})});alert('Student created.\n\nStudent ID: '+d.credentials.student_code+'\nPassword: '+d.credentials.password);load()}catch(e){alert(e.message)}}load()}
 window.addEventListener('DOMContentLoaded',()=>{addCss();setTimeout(addQuickTool,50)});
})();

/* DHYEYA V2 — Dynamic greeting, quote, notifications and Battle Arena */
(()=>{
 const nf=window.NexusFoundation;if(!nf)return;const api=nf.api;
 const esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
 const quotes=[
  ['Nelson Mandela','It always seems impossible until it’s done.'],
  ['A. P. J. Abdul Kalam','Dream, dream, dream. Dreams transform into thoughts and thoughts result in action.'],
  ['Steve Jobs','The only way to do great work is to love what you do.'],
  ['Albert Einstein','Genius is 1% inspiration and 99% perspiration.'],
  ['Confucius','It does not matter how slowly you go as long as you do not stop.'],
  ['Winston Churchill','Success is not final; failure is not fatal: it is the courage to continue that counts.']
 ];
 const css=`
 .dhy-v2-quote{margin:14px 0 16px;padding:18px 20px;border:1px solid rgba(255,255,255,.09);border-radius:20px;background:linear-gradient(135deg,rgba(255,178,82,.10),rgba(126,91,255,.06));box-shadow:0 12px 35px rgba(20,30,55,.06);display:flex;gap:14px;align-items:flex-start}.dhy-v2-quote-mark{font-size:32px;line-height:1;color:#f39a2d;font-weight:900}.dhy-v2-quote-text{font-size:14px;line-height:1.55;color:#343b49;font-weight:700}.dhy-v2-quote-by{margin-top:7px;font-size:11px;color:#8b93a3;font-weight:800;letter-spacing:.05em}.dhy-v2-bell{position:relative;border:1px solid rgba(20,25,35,.10);background:#fff;color:#232938;border-radius:14px;width:44px;height:44px;cursor:pointer;font-size:19px;box-shadow:0 6px 18px rgba(20,25,35,.06)}.dhy-v2-badge{position:absolute;right:-3px;top:-4px;min-width:17px;height:17px;border-radius:999px;background:#f26d4f;color:#fff;font-size:9px;font-weight:900;display:grid;place-items:center;padding:0 4px}.dhy-v2-modal{position:fixed;inset:0;z-index:12000;background:rgba(13,17,25,.56);backdrop-filter:blur(12px);display:flex;align-items:center;justify-content:center;padding:16px}.dhy-v2-card{width:min(760px,96vw);max-height:90vh;overflow:auto;background:rgba(255,255,255,.97);border:1px solid rgba(255,255,255,.8);border-radius:28px;box-shadow:0 35px 100px rgba(0,0,0,.25);color:#1c2331}.dhy-v2-head{padding:22px 24px;border-bottom:1px solid #edf0f5;display:flex;align-items:flex-start;justify-content:space-between;gap:15px}.dhy-v2-head h2{margin:4px 0;font-size:24px}.dhy-v2-kicker{font-size:10px;letter-spacing:.15em;color:#a16b2c;font-weight:900}.dhy-v2-close{border:0;background:#171d26;color:#fff;border-radius:12px;width:40px;height:40px;font-size:20px;cursor:pointer}.dhy-v2-body{padding:20px 24px}.dhy-v2-list{display:grid;gap:10px}.dhy-v2-notif{padding:15px;border:1px solid #e9edf3;border-radius:17px;background:#fff;cursor:pointer}.dhy-v2-notif.unread{border-color:#f2b05d;background:#fffaf2}.dhy-v2-notif-title{font-weight:900;font-size:14px}.dhy-v2-notif-msg{font-size:12px;color:#687183;margin-top:5px;line-height:1.45}.dhy-v2-notif-meta{font-size:10px;color:#9aa2b0;margin-top:8px}.dhy-v2-popup{position:fixed;right:22px;top:76px;z-index:13000;width:min(390px,calc(100vw - 28px));background:#171d26;color:#fff;border-radius:20px;padding:17px;box-shadow:0 24px 70px rgba(0,0,0,.30);animation:dhyPop .28s ease}.dhy-v2-popup-top{display:flex;justify-content:space-between;gap:12px}.dhy-v2-popup-title{font-weight:900}.dhy-v2-popup-msg{color:#cbd2dc;font-size:12px;line-height:1.5;margin-top:7px}.dhy-v2-popup-action{display:inline-block;margin-top:12px;background:#ffac43;color:#15110c;border-radius:11px;padding:9px 12px;font-size:11px;font-weight:900;text-decoration:none}.dhy-v2-battle-tabs{display:flex;gap:8px;margin-bottom:14px}.dhy-v2-tab{border:1px solid #e5e9ef;background:#fff;border-radius:12px;padding:9px 12px;font-weight:850;cursor:pointer}.dhy-v2-tab.active{background:#171d26;color:#fff;border-color:#171d26}.dhy-v2-battle-grid{display:grid;grid-template-columns:1.1fr .9fr;gap:14px}.dhy-v2-panel{border:1px solid #e9edf3;border-radius:18px;padding:16px;background:#fff}.dhy-v2-panel h3{margin:0 0 10px;font-size:15px}.dhy-v2-field{width:100%;box-sizing:border-box;border:1px solid #dfe4eb;border-radius:12px;padding:10px 11px;margin:5px 0 9px;background:#fff;font:inherit}.dhy-v2-primary{border:0;background:linear-gradient(135deg,#ffb04a,#f18922);color:#17120c;border-radius:13px;padding:11px 15px;font-weight:950;cursor:pointer}.dhy-v2-ghost{border:1px solid #dfe4eb;background:#fff;border-radius:12px;padding:10px 13px;font-weight:850;cursor:pointer}.dhy-v2-online{display:flex;align-items:center;gap:10px;padding:10px 0;border-bottom:1px solid #eef1f5}.dhy-v2-online:last-child{border-bottom:0}.dhy-v2-dot{width:8px;height:8px;background:#37c77a;border-radius:50%;box-shadow:0 0 0 4px rgba(55,199,122,.12)}.dhy-v2-avatar{width:34px;height:34px;border-radius:12px;object-fit:cover;background:#edf0f5;display:grid;place-items:center;font-weight:900}.dhy-v2-online-main{flex:1;min-width:0}.dhy-v2-online-name{font-weight:850;font-size:12px}.dhy-v2-online-sub{font-size:10px;color:#8b94a3;margin-top:2px}.dhy-v2-battle-question{font-size:18px;font-weight:850;line-height:1.45;margin:16px 0}.dhy-v2-option{display:block;width:100%;text-align:left;border:1px solid #e0e5eb;background:#fff;border-radius:14px;padding:12px;margin:8px 0;cursor:pointer;font:inherit}.dhy-v2-option.selected{border-color:#f29a2d;background:#fff6e9;box-shadow:0 0 0 3px rgba(242,154,45,.10)}.dhy-v2-scorebar{display:grid;grid-template-columns:1fr 1fr;gap:10px}.dhy-v2-score{border-radius:16px;background:#f7f8fa;padding:13px}.dhy-v2-score b{display:block;font-size:20px}.dhy-v2-result{text-align:center;padding:28px}.dhy-v2-result h2{font-size:30px;margin:8px 0}.dhy-v2-muted{color:#7b8492;font-size:12px}@keyframes dhyPop{from{opacity:0;transform:translateY(-8px) scale(.98)}to{opacity:1;transform:none}}@media(max-width:700px){.dhy-v2-battle-grid{grid-template-columns:1fr}.dhy-v2-card{border-radius:24px}.dhy-v2-head,.dhy-v2-body{padding:17px}.dhy-v2-quote{padding:15px}.dhy-v2-bell{width:40px;height:40px}}
 `;
 function addCss(){if(document.getElementById('dhyV2Css'))return;const s=document.createElement('style');s.id='dhyV2Css';s.textContent=css;document.head.appendChild(s)}
 function hourGreeting(){const h=new Date().getHours();if(h>=5&&h<12)return 'Good morning';if(h>=12&&h<17)return 'Good afternoon';if(h>=17&&h<21)return 'Good evening';return 'Good night'}
 function personalizeGreeting(){const u=nf.getStudent?.();const h=document.querySelector('.hero h1');if(!h||!u)return;const name=u.name?.trim()||'there';h.innerHTML=`${hourGreeting()}, <span class="gold">${esc(name)}.</span>`;let q=document.getElementById('dhyV2Quote');if(!q){q=document.createElement('div');q.id='dhyV2Quote';q.className='dhy-v2-quote';const hero=document.querySelector('.hero');if(hero)hero.insertAdjacentElement('afterend',q)}const idx=(new Date().getDate()+new Date().getMonth())%quotes.length;const [who,text]=quotes[idx];q.innerHTML=`<div class="dhy-v2-quote-mark">“</div><div><div class="dhy-v2-quote-text">${esc(text)}</div><div class="dhy-v2-quote-by">— ${esc(who)}</div></div>`}
 function showPopup(n){const old=document.querySelector('.dhy-v2-popup');if(old)old.remove();const p=document.createElement('div');p.className='dhy-v2-popup';p.innerHTML=`<div class="dhy-v2-popup-top"><div><div class="dhy-v2-kicker" style="color:#ffb24e">DHYEYA UPDATE</div><div class="dhy-v2-popup-title">${esc(n.title)}</div></div><button class="dhy-v2-close" style="width:30px;height:30px" aria-label="Close">×</button></div><div class="dhy-v2-popup-msg">${esc(n.message)}</div>${n.action_url?`<a class="dhy-v2-popup-action" href="${esc(n.action_url)}">Open →</a>`:''}`;document.body.appendChild(p);p.querySelector('button').onclick=()=>p.remove();setTimeout(()=>p.remove(),9000)}
 async function notificationData(){try{return await api('/notifications')}catch{return {notifications:[],unread:0}}}
 function mountBell(){const actions=document.querySelector('.top-actions');if(!actions||document.getElementById('dhyV2Bell'))return;const b=document.createElement('button');b.id='dhyV2Bell';b.className='dhy-v2-bell';b.innerHTML='🔔<span id="dhyV2Badge" class="dhy-v2-badge" style="display:none">0</span>';b.title='Notifications';b.onclick=openNotifications;actions.insertBefore(b,actions.firstChild)}
 async function refreshBadge(){const d=await notificationData();const b=document.getElementById('dhyV2Badge');if(b){b.textContent=d.unread>9?'9+':d.unread;b.style.display=d.unread?'grid':'none'}}
 async function openNotifications(){addCss();const d=await notificationData();const m=document.createElement('div');m.className='dhy-v2-modal';m.innerHTML=`<div class="dhy-v2-card"><div class="dhy-v2-head"><div><div class="dhy-v2-kicker">DHYEYA • NOTIFICATIONS</div><h2>Updates for you</h2><div class="dhy-v2-muted">Announcements, new tests and important updates.</div></div><button class="dhy-v2-close">×</button></div><div class="dhy-v2-body"><div class="dhy-v2-list" id="dhyNotifList">${(d.notifications||[]).map(n=>`<div class="dhy-v2-notif ${n.read_at?'':'unread'}" data-id="${n.id}" ${n.action_url?`data-url="${esc(n.action_url)}"`:''}><div class="dhy-v2-notif-title">${esc(n.title)}</div><div class="dhy-v2-notif-msg">${esc(n.message)}</div><div class="dhy-v2-notif-meta">${new Date(n.created_at).toLocaleString()}</div></div>`).join('')||'<div class="dhy-v2-muted">No notifications yet.</div>'}</div></div></div>`;document.body.appendChild(m);m.querySelector('.dhy-v2-close').onclick=()=>m.remove();m.addEventListener('click',e=>{if(e.target===m)m.remove()});m.querySelectorAll('.dhy-v2-notif').forEach(x=>x.onclick=async()=>{await api('/notifications/'+x.dataset.id+'/read',{method:'PATCH'}).catch(()=>{});if(x.dataset.url)location.href=x.dataset.url;x.classList.remove('unread');refreshBadge()});}
 function connectRealtime(){try{const es=new EventSource('/api/realtime');es.addEventListener('notification',e=>{try{const n=JSON.parse(e.data);showPopup(n);refreshBadge()}catch{}});es.addEventListener('battle_invite',e=>{try{const n=JSON.parse(e.data);showBattleInvite(n)}catch{}});es.addEventListener('battle_accepted',e=>{try{const n=JSON.parse(e.data);if(n.battle_id)openBattle(n.battle_id)}catch{}});es.addEventListener('battle_started',e=>{try{const n=JSON.parse(e.data);if(n.battle_id)openBattle(n.battle_id,true)}catch{}});es.addEventListener('battle_complete',e=>{try{const n=JSON.parse(e.data);if(n.battle_id)toast('⚔️ Battle complete')}catch{}});es.onerror=()=>{es.close();setTimeout(connectRealtime,5000)}}catch{}}
 function addBattleTool(){const grid=document.querySelector('#utilityPanel .utility-grid');if(!grid||document.getElementById('dhyBattleTool'))return;const b=document.createElement('button');b.id='dhyBattleTool';b.className='utility-item';b.innerHTML='<span class="uicon">⚔️</span><span><b>Battle Arena</b><small>Challenge online aspirants</small></span>';b.onclick=()=>{closeUtilityHub?.();openBattleArena()};grid.appendChild(b)}
 function modal(inner){const m=document.createElement('div');m.className='dhy-v2-modal';m.innerHTML=inner;document.body.appendChild(m);return m}
 async function openBattleArena(){addCss();const m=modal(`<div class="dhy-v2-card"><div class="dhy-v2-head"><div><div class="dhy-v2-kicker">DHYEYA • BATTLE ARENA</div><h2>⚔️ Quiz Battle</h2><div class="dhy-v2-muted">Challenge everyone online. The first player to accept gets the match.</div></div><button class="dhy-v2-close">×</button></div><div class="dhy-v2-body"><div class="dhy-v2-battle-tabs"><button class="dhy-v2-tab active" data-tab="create">Create Battle</button><button class="dhy-v2-tab" data-tab="online">Online Now</button></div><div id="dhyBattleContent"></div></div></div>`);m.querySelector('.dhy-v2-close').onclick=()=>m.remove();const content=m.querySelector('#dhyBattleContent');
 function createView(){content.innerHTML=`<div class="dhy-v2-battle-grid"><div class="dhy-v2-panel"><h3>Open a challenge</h3><label class="dhy-v2-muted">Subject</label><input id="dbSubject" class="dhy-v2-field" placeholder="e.g. Science (optional)"><label class="dhy-v2-muted">Topic</label><input id="dbTopic" class="dhy-v2-field" placeholder="e.g. Biology (optional)"><label class="dhy-v2-muted">Questions</label><select id="dbCount" class="dhy-v2-field"><option>10</option><option>15</option><option>20</option></select><label class="dhy-v2-muted">Time per question</label><select id="dbTime" class="dhy-v2-field"><option value="20">20 seconds</option><option value="30">30 seconds</option><option value="15">15 seconds</option></select><button class="dhy-v2-primary" id="dbCreate">⚔️ Challenge Everyone</button></div><div class="dhy-v2-panel"><h3>Open battles</h3><div id="dbOpen" class="dhy-v2-muted">Loading…</div></div></div>`;m.querySelector('#dbCreate').onclick=async()=>{try{const b=await api('/battles',{method:'POST',body:JSON.stringify({subject:m.querySelector('#dbSubject').value.trim()||null,topic:m.querySelector('#dbTopic').value.trim()||null,question_count:Number(m.querySelector('#dbCount').value),time_per_question_seconds:Number(m.querySelector('#dbTime').value)})});toast('⚔️ Battle opened — waiting for an opponent');openBattle(b.battle.id)}catch(e){alert(e.message)}};loadOpen()}
 async function loadOpen(){try{const d=await api('/battles/open');const el=m.querySelector('#dbOpen');if(!el)return;el.innerHTML=(d.battles||[]).map(b=>`<div class="dhy-v2-online"><span class="dhy-v2-dot"></span><div class="dhy-v2-online-main"><div class="dhy-v2-online-name">${esc(b.creator_name)}</div><div class="dhy-v2-online-sub">${esc(b.subject||'Mixed')} • ${b.question_count} questions</div></div><button class="dhy-v2-ghost" data-accept="${b.id}">Accept</button></div>`).join('')||'No open battles right now.';el.querySelectorAll('[data-accept]').forEach(btn=>btn.onclick=async()=>{try{await api('/battles/'+btn.dataset.accept+'/accept',{method:'POST'});m.remove();openBattle(btn.dataset.accept,true)}catch(e){alert(e.message);loadOpen()}})}catch{}}
 async function onlineView(){content.innerHTML=`<div class="dhy-v2-panel"><h3>🟢 Online aspirants</h3><div id="dbOnline" class="dhy-v2-muted">Loading…</div></div>`;try{const d=await api('/online-users');const el=m.querySelector('#dbOnline');el.innerHTML=(d.users||[]).map(u=>`<div class="dhy-v2-online"><span class="dhy-v2-dot"></span><div class="dhy-v2-avatar">${u.avatar_url?`<img src="${esc(u.avatar_url)}" style="width:100%;height:100%;border-radius:inherit;object-fit:cover">`:esc((u.name||'S')[0])}</div><div class="dhy-v2-online-main"><div class="dhy-v2-online-name">${esc(u.name)}</div><div class="dhy-v2-online-sub">Level ${u.level||1} • ${u.xp||0} XP</div></div></div>`).join('')||'No other students are online.'}catch(e){m.querySelector('#dbOnline').textContent=e.message}}
 m.querySelectorAll('.dhy-v2-tab').forEach(t=>t.onclick=()=>{m.querySelectorAll('.dhy-v2-tab').forEach(x=>x.classList.remove('active'));t.classList.add('active');t.dataset.tab==='create'?createView():onlineView()});createView();}
 function showBattleInvite(n){if(document.querySelector('[data-battle-invite]'))return;const p=modal(`<div class="dhy-v2-card" data-battle-invite><div class="dhy-v2-body" style="padding:28px;text-align:center"><div style="font-size:44px">⚔️</div><div class="dhy-v2-kicker">BATTLE CHALLENGE</div><h2 style="margin:8px 0">${esc(n.creator?.name||'An aspirant')} challenged everyone</h2><p class="dhy-v2-muted">${esc(n.subject||'Mixed')} • ${n.question_count} questions • ${n.time_per_question_seconds}s/question</p><div style="display:flex;gap:9px;justify-content:center;margin-top:18px"><button id="dbAcceptInvite" class="dhy-v2-primary">Accept Battle</button><button id="dbDeclineInvite" class="dhy-v2-ghost">Not now</button></div></div></div>`);p.querySelector('#dbDeclineInvite').onclick=()=>p.remove();p.querySelector('#dbAcceptInvite').onclick=async()=>{try{await api('/battles/'+n.battle_id+'/accept',{method:'POST'});p.remove();openBattle(n.battle_id,true)}catch(e){p.remove();toast(e.message)}}}
 async function openBattle(id,autoStart=false){addCss();const existing=document.querySelector(`.dhy-v2-modal[data-battle-id="${id}"]`);if(existing)existing.remove();const m=modal(`<div class="dhy-v2-card"><div class="dhy-v2-head"><div><div class="dhy-v2-kicker">DHYEYA • LIVE MATCH</div><h2>⚔️ Battle Arena</h2><div id="dbMatchSub" class="dhy-v2-muted">Loading match…</div></div><button class="dhy-v2-close">×</button></div><div class="dhy-v2-body" id="dbBattleBody"></div></div>`);m.setAttribute('data-battle-id',id);m.querySelector('.dhy-v2-close').onclick=()=>m.remove();const body=m.querySelector('#dbBattleBody');let battleData=null;let qIndex=0;let startedAt=Date.now();let selected=null;let timer=null;let poll=null;
 async function load(){const d=await api('/battles/'+id);battleData=d;m.querySelector('#dbMatchSub').textContent=`${d.battle.creator_name||'Player'} vs ${d.battle.opponent_name||'Opponent'} • ${d.battle.question_count} questions`;if(d.battle.status==='open'){body.innerHTML='<div class="dhy-v2-result"><div style="font-size:50px">⏳</div><h2>Waiting for an opponent</h2><p class="dhy-v2-muted">Keep this screen open. The first online aspirant to accept your challenge will join.</p><button class="dhy-v2-ghost" id="dbCancel">Cancel Battle</button></div>';body.querySelector('#dbCancel').onclick=async()=>{await api('/battles/'+id+'/cancel',{method:'POST'}).catch(()=>{});m.remove()};return}if(['starting'].includes(d.battle.status)){if(autoStart||d.battle.opponent_user_id){await api('/battles/'+id+'/start',{method:'POST'}).catch(()=>{});return load()}}if(d.battle.status==='completed'){renderResult(d);return}if(d.battle.status!=='active'){body.innerHTML='<div class="dhy-v2-result"><h2>Battle unavailable</h2><p class="dhy-v2-muted">'+esc(d.battle.status)+'</p></div>';return}renderQuestion(d)}
 function renderQuestion(d){clearInterval(timer);qIndex=Math.min(qIndex,d.questions.length-1);const q=d.questions[qIndex];const mine=d.answers.find(a=>a.user_id===nf.getStudent().id&&a.question_no===q.question_no);if(mine){qIndex=Math.min(qIndex+1,d.questions.length-1);if(qIndex!==q.question_no-1)return renderQuestion(d)}selected=null;startedAt=Date.now();body.innerHTML=`<div class="dhy-v2-scorebar"><div class="dhy-v2-score"><span class="dhy-v2-muted">YOU</span><b id="dbMyScore">${d.answers.filter(a=>a.user_id===nf.getStudent().id).reduce((x,a)=>x+(a.points||0),0)}</b></div><div class="dhy-v2-score"><span class="dhy-v2-muted">OPPONENT</span><b id="dbOppScore">${d.answers.filter(a=>a.user_id!==nf.getStudent().id).reduce((x,a)=>x+(a.points||0),0)}</b></div></div><div class="dhy-v2-muted" style="margin-top:14px">Question ${q.question_no} / ${d.questions.length}</div><div class="dhy-v2-battle-question">${esc(q.question_en||q.question_hi||'')}</div><div id="dbOpts">${(q.options||[]).map((o,i)=>`<button class="dhy-v2-option" data-opt="${i}">${esc(typeof o==='string'?o:(o.text||o.en||JSON.stringify(o)))}</button>`).join('')}</div><div style="display:flex;justify-content:space-between;align-items:center;margin-top:14px"><span id="dbTimer" class="dhy-v2-muted">${d.battle.time_per_question_seconds}s</span><button id="dbSubmit" class="dhy-v2-primary">Submit Answer →</button></div>`;body.querySelectorAll('[data-opt]').forEach(x=>x.onclick=()=>{selected=Number(x.dataset.opt);body.querySelectorAll('[data-opt]').forEach(y=>y.classList.remove('selected'));x.classList.add('selected')});let left=d.battle.time_per_question_seconds;timer=setInterval(()=>{left--;const t=body.querySelector('#dbTimer');if(t)t.textContent=left+'s';if(left<=0){clearInterval(timer);submit()}},1000);body.querySelector('#dbSubmit').onclick=submit;async function submit(){if(!body.isConnected)return;clearInterval(timer);const ms=Date.now()-startedAt;try{await api('/battles/'+id+'/answer',{method:'POST',body:JSON.stringify({question_no:q.question_no,selected_option:selected,response_ms:ms})});const nd=await api('/battles/'+id);if(nd.battle.status==='completed'){renderResult(nd)}else{qIndex++;renderQuestion(nd)}}catch(e){toast(e.message)}}}
 function renderResult(d){clearInterval(timer);clearInterval(poll);const my=nf.getStudent().id;const myScore=d.answers.filter(a=>a.user_id===my).reduce((x,a)=>x+(a.points||0),0);const oppScore=d.answers.filter(a=>a.user_id!==my).reduce((x,a)=>x+(a.points||0),0);const winner=d.battle.winner_user_id;body.innerHTML=`<div class="dhy-v2-result"><div style="font-size:56px">${winner===my?'🏆':'⚔️'}</div><div class="dhy-v2-kicker">BATTLE COMPLETE</div><h2>${winner===my?'Victory!':winner?'Battle over':'Draw'}</h2><div class="dhy-v2-scorebar" style="margin-top:20px"><div class="dhy-v2-score"><span class="dhy-v2-muted">YOU</span><b>${myScore}</b></div><div class="dhy-v2-score"><span class="dhy-v2-muted">OPPONENT</span><b>${oppScore}</b></div></div><button class="dhy-v2-primary" style="margin-top:20px" onclick="this.closest('.dhy-v2-modal').remove()">Done</button></div>`}
 load();poll=setInterval(()=>{if(!m.isConnected)return;load().catch(()=>{})},3000);
 }
 window.DhyeeyaV2={openBattleArena,openBattle,openNotifications};
 function boot(){addCss();mountBell();personalizeGreeting();addBattleTool();refreshBadge();notificationData().then(d=>{const latest=(d.notifications||[]).find(n=>!n.read_at);if(latest)showPopup(latest)});connectRealtime();setInterval(()=>{personalizeGreeting();refreshBadge();fetch('/api/presence',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({})}).catch(()=>{})},15000)}
 window.addEventListener('DOMContentLoaded',()=>setTimeout(boot,350));
})();

/* DHYEYA V2 — Admin notification composer enhancement */
(()=>{
 const nf=window.NexusFoundation;if(!nf)return;const api=nf.api;const esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
 function inject(){const body=document.querySelector('.dhy-admin-body');if(!body||document.getElementById('dhyAdminNotifyV2'))return;const sec=document.createElement('div');sec.id='dhyAdminNotifyV2';sec.className='dhy-admin-section';sec.innerHTML=`<h3>🔔 Broadcast Notification</h3><div class="dhy-admin-sub" style="margin-bottom:10px">Send an instant popup to every active student. The notification is also saved to their notification centre.</div><input id="dhyNTitle" class="dhy-admin-input" placeholder="Notification title"><textarea id="dhyNMsg" class="dhy-admin-input" style="min-height:80px;resize:vertical" placeholder="Write the announcement…"></textarea><select id="dhyNType" class="dhy-admin-input"><option value="announcement">📢 Announcement</option><option value="new_test">🧪 New Test</option><option value="revision">📚 Revision</option><option value="important">⚡ Important</option><option value="offer">🎁 Offer</option><option value="system">🛠️ System</option></select><input id="dhyNUrl" class="dhy-admin-input" placeholder="Optional link (e.g. /tests)"><button id="dhyNSend" class="dhy-admin-primary">Send to All Active Students</button><div id="dhyNStatus" class="dhy-admin-sub" style="margin-top:8px"></div></div>`;body.insertBefore(sec,body.firstChild);sec.querySelector('#dhyNSend').onclick=async()=>{const st=sec.querySelector('#dhyNStatus');try{const title=sec.querySelector('#dhyNTitle').value.trim(),message=sec.querySelector('#dhyNMsg').value.trim();if(!title||!message)throw Error('Title and message are required');const d=await api('/admin/notifications',{method:'POST',body:JSON.stringify({title,message,notification_type:sec.querySelector('#dhyNType').value,action_url:sec.querySelector('#dhyNUrl').value.trim()||null})});st.textContent=`✓ Sent to ${d.recipients} active students`;sec.querySelector('#dhyNTitle').value='';sec.querySelector('#dhyNMsg').value='';sec.querySelector('#dhyNUrl').value='';}catch(e){st.textContent='Error: '+e.message}}}
 const mo=new MutationObserver(inject);mo.observe(document.body,{childList:true,subtree:true});setInterval(inject,1000);
})();
